package com.klu.application_service;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import com.klu.application_service.security.JwtService;
import java.util.*;
@RestController @RequestMapping("/api/applications")
public class ApplicationController {
 private final ApplicationRepository applications;
 private final ApplicationService service;
 private final JwtService jwt;
 public ApplicationController(ApplicationRepository applications,ApplicationService service,JwtService jwt){this.applications=applications;this.service=service;this.jwt=jwt;}
 @GetMapping public ResponseEntity<?> all(@RequestHeader(value="Authorization",required=false) String authorization){ResponseEntity<?> denied=authorizeRecruiter(authorization);return denied!=null?denied:ResponseEntity.ok(applications.findAll());}
 @GetMapping("/candidate/{email}") public ResponseEntity<?> candidate(@PathVariable String email,@RequestHeader(value="Authorization",required=false) String authorization){ResponseEntity<?> denied=authorizeCandidate(email,authorization);if(denied!=null)return denied;try{return ResponseEntity.ok(service.findByCandidate(email));}catch(IllegalArgumentException e){return ResponseEntity.badRequest().body(e.getMessage());}}
 @PostMapping public ResponseEntity<?> apply(@RequestBody Application application,@RequestHeader(value="Authorization",required=false) String authorization){String email=application==null?null:application.getCandidate();ResponseEntity<?> denied=authorizeCandidate(email,authorization);if(denied!=null)return denied;try{return ResponseEntity.status(HttpStatus.CREATED).body(service.create(application));}catch(IllegalArgumentException e){if(e.getMessage().contains("already applied"))return ResponseEntity.status(HttpStatus.CONFLICT).body(e.getMessage());if(e.getMessage().equals("Job not found"))return ResponseEntity.status(HttpStatus.NOT_FOUND).body(e.getMessage());return ResponseEntity.badRequest().body(e.getMessage());}}
 @PutMapping("/{id}/status") public ResponseEntity<?> status(@PathVariable Long id,@RequestParam String value,@RequestHeader(value="Authorization",required=false) String authorization){ResponseEntity<?> denied=authorizeRecruiter(authorization);if(denied!=null)return denied;try{return ResponseEntity.ok(service.updateStatus(id,value));}catch(IllegalArgumentException e){return ResponseEntity.status(e.getMessage().equals("Application not found")?HttpStatus.NOT_FOUND:HttpStatus.BAD_REQUEST).body(e.getMessage());}}
 @PutMapping("/{id}/interview") public ResponseEntity<?> interview(@PathVariable Long id,@RequestParam java.time.LocalDateTime value,@RequestHeader(value="Authorization",required=false) String authorization){ResponseEntity<?> denied=authorizeRecruiter(authorization);if(denied!=null)return denied;try{return ResponseEntity.ok(service.updateInterviewTime(id,value));}catch(IllegalArgumentException e){return ResponseEntity.status(e.getMessage().equals("Application not found")?HttpStatus.NOT_FOUND:HttpStatus.BAD_REQUEST).body(e.getMessage());}}
 @GetMapping("/pipeline") public Map<String,Long> pipeline(){return Map.of("applied",applications.countByStatus("APPLIED"),"shortlisted",applications.countByStatus("SHORTLISTED"),"interview",applications.countByStatus("INTERVIEW"),"hired",applications.countByStatus("HIRED"));}
 private ResponseEntity<?> authorizeCandidate(String email,String authorization){if(authorization==null||!authorization.startsWith("Bearer "))return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Bearer token is required");JwtService.Claims claims=jwt.read(authorization.substring(7).trim());if(claims==null)return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Invalid or expired token");if(!isCandidateRole(claims.role()))return ResponseEntity.status(HttpStatus.FORBIDDEN).body("Candidate access is required");if(email==null||!claims.email().equalsIgnoreCase(email))return ResponseEntity.status(HttpStatus.FORBIDDEN).body("You can only access your own applications");return null;}
 private boolean isCandidateRole(String role){return "JOB_SEEKER".equalsIgnoreCase(role)||"CANDIDATE".equalsIgnoreCase(role);}
 private ResponseEntity<?> authorizeRecruiter(String authorization){if(authorization==null||!authorization.startsWith("Bearer "))return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Bearer token is required");JwtService.Claims claims=jwt.read(authorization.substring(7).trim());if(claims==null)return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Invalid or expired token");if(!"RECRUITER".equalsIgnoreCase(claims.role())&& !"ADMIN".equalsIgnoreCase(claims.role()))return ResponseEntity.status(HttpStatus.FORBIDDEN).body("Recruiter access is required");return null;}
}
